-- RPC function for transactional operations support
-- These functions help manage transactions in Supabase

-- Begin transaction function
CREATE OR REPLACE FUNCTION begin_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically handles transactions within functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Commit transaction function
CREATE OR REPLACE FUNCTION commit_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically commits at the end of functions
    -- This is a placeholder for consistency with the ImportService
    NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Rollback transaction function
CREATE OR REPLACE FUNCTION rollback_transaction()
RETURNS void AS $$
BEGIN
    -- Supabase automatically rolls back on errors
    -- This is a placeholder for consistency with the ImportService
    RAISE EXCEPTION 'Transaction rollback requested';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Main import function for complete list structures
CREATE OR REPLACE FUNCTION import_complete_list(
    p_user_id UUID,
    p_list_data JSONB,
    p_categories_data JSONB,
    p_listed_gear_items_data JSONB
)
RETURNS JSONB AS $$
DECLARE
    v_list_id UUID;
    v_category JSONB;
    v_category_id UUID;
    v_category_map JSONB := '{}'::JSONB;
    v_gear_item JSONB;
    v_gear_id UUID;
    v_gear_map JSONB := '{}'::JSONB;
    v_listed_item JSONB;
    v_existing_gear RECORD;
    v_metadata JSONB;
    v_gear_items_created INT := 0;
    v_gear_items_reused INT := 0;
    v_categories_created INT := 0;
    v_listed_items_created INT := 0;
    v_all_gear_ids UUID[] := '{}';
BEGIN
    -- Create the list
    INSERT INTO lists (name, user_id, gear_ids)
    VALUES (
        p_list_data->>'name',
        p_user_id,
        ARRAY[]::UUID[]
    )
    RETURNING id INTO v_list_id;

    -- Create categories and build mapping
    FOR v_category IN SELECT * FROM jsonb_array_elements(p_categories_data)
    LOOP
        INSERT INTO list_categories (
            list_id,
            name,
            sort_index,
            icon,
            color
        )
        VALUES (
            v_list_id,
            v_category->>'name',
            (v_category->>'sort_index')::INTEGER,
            v_category->>'icon',
            v_category->>'color'
        )
        RETURNING id INTO v_category_id;

        v_category_map := jsonb_set(v_category_map, ARRAY[v_category->>'name'], to_jsonb(v_category_id));
        v_categories_created := v_categories_created + 1;
    END LOOP;

    -- Process gear items and create listed gear items
    FOR v_listed_item IN SELECT * FROM jsonb_array_elements(p_listed_gear_items_data)
    LOOP
        v_gear_item := v_listed_item->'gearItem';

        -- Check if gear item already exists for this user
        SELECT id INTO v_existing_gear
        FROM gear_items
        WHERE user_id = p_user_id
            AND LOWER(TRIM(description)) = LOWER(TRIM(v_gear_item->>'description'))
            AND ABS(weight_g - (v_gear_item->>'weight_g')::INTEGER) <= 5
        LIMIT 1;

        IF FOUND THEN
            -- Reuse existing gear item
            v_gear_id := v_existing_gear.id;
            v_gear_items_reused := v_gear_items_reused + 1;
        ELSE
            -- Create new gear item
            INSERT INTO gear_items (
                user_id,
                description,
                item_type,
                brand,
                model,
                weight_g,
                weight_unit_display,
                consumable,
                price,
                notes,
                image_url,
                url
            )
            VALUES (
                p_user_id,
                v_gear_item->>'description',
                v_gear_item->>'item_type',
                v_gear_item->>'brand',
                v_gear_item->>'model',
                (v_gear_item->>'weight_g')::INTEGER,
                v_gear_item->>'weight_unit_display',
                (v_gear_item->>'consumable')::BOOLEAN,
                (v_gear_item->>'price')::NUMERIC,
                v_gear_item->>'notes',
                v_gear_item->>'image_url',
                v_gear_item->>'url'
            )
            RETURNING id INTO v_gear_id;

            v_gear_items_created := v_gear_items_created + 1;
        END IF;

        -- Add gear_id to array for list
        v_all_gear_ids := array_append(v_all_gear_ids, v_gear_id);

        -- Create listed gear item
        INSERT INTO listed_gear_items (
            gear_id,
            list_category_id,
            quantity,
            worn,
            weight_g_override,
            notes,
            sort_index
        )
        VALUES (
            v_gear_id,
            (v_category_map->>(v_listed_item->>'categoryName'))::UUID,
            (v_listed_item->>'quantity')::INTEGER,
            (v_listed_item->>'worn')::BOOLEAN,
            (v_listed_item->>'weight_g_override')::INTEGER,
            v_listed_item->>'notes',
            (v_listed_item->>'sort_index')::INTEGER
        );

        v_listed_items_created := v_listed_items_created + 1;
    END LOOP;

    -- Update list with all gear_ids for legacy compatibility
    UPDATE lists 
    SET gear_ids = v_all_gear_ids
    WHERE id = v_list_id;

    -- Build return metadata
    v_metadata := jsonb_build_object(
        'gearItemsCreated', v_gear_items_created,
        'gearItemsReused', v_gear_items_reused,
        'categoriesCreated', v_categories_created,
        'listedGearItemsCreated', v_listed_items_created
    );

    -- Return the created list and metadata
    RETURN jsonb_build_object(
        'list', (SELECT row_to_json(lists.*) FROM lists WHERE id = v_list_id),
        'metadata', v_metadata
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant execute permissions
GRANT EXECUTE ON FUNCTION begin_transaction() TO authenticated;
GRANT EXECUTE ON FUNCTION commit_transaction() TO authenticated;
GRANT EXECUTE ON FUNCTION rollback_transaction() TO authenticated;
GRANT EXECUTE ON FUNCTION import_complete_list(UUID, JSONB, JSONB, JSONB) TO authenticated;

import { supabase } from './supabase'
import { createGearRepository } from './gearRepository'
import { createListRepository } from './listRepository'
import type { 
  ListParseResult, 
  ParsedList, 
  ParsedListCategory, 
  ParsedListedGearItem 
} from '@/utils/parser'
import type { 
  List, 
  ListCategory, 
  ListedGearItem, 
  GearItem 
} from '@/types/database'

interface ImportResult {
  success: boolean
  list?: List
  errors: string[]
  warnings: string[]
  metadata?: {
    gearItemsCreated: number
    gearItemsReused: number
    categoriesCreated: number
    listedGearItemsCreated: number
  }
}

class ImportService {
  private readonly userId: string

  constructor(userId: string) {
    this.userId = userId
  }

  /**
   * Import a complete list structure in a single database transaction
   * This ensures atomicity - either everything is created or nothing is created
   */
  async importList(parseResult: ListParseResult): Promise<ImportResult> {
    const result: ImportResult = {
      success: false,
      errors: [],
      warnings: [],
      metadata: {
        gearItemsCreated: 0,
        categoriesCreated: 0,
        listedGearItemsCreated: 0
      }
    }

    // Early validation
    if (!parseResult.success || parseResult.errors.length > 0) {
      result.errors.push(...parseResult.errors)
      return result
    }

    if (parseResult.listedGearItems.length === 0) {
      result.errors.push('No items to import')
      return result
    }

    try {
      // Check for duplicate list name and adjust if necessary
      const finalListName = await this.getUniqueListName(parseResult.list.name)
      if (finalListName !== parseResult.list.name) {
        result.warnings.push(`List name changed from "${parseResult.list.name}" to "${finalListName}" to avoid duplicates`)
      }

      // Execute the entire import in a single transaction
      const importedList = await this.executeTransactionalImport({
        ...parseResult,
        list: { ...parseResult.list, name: finalListName }
      })

      result.success = true
      result.list = importedList.list
      result.metadata = importedList.metadata
      result.warnings.push(...parseResult.warnings)

      // Add helpful import summary
      if (importedList.metadata.gearItemsReused > 0) {
        result.warnings.push(`Reused ${importedList.metadata.gearItemsReused} existing gear items from your library`)
      }
      if (importedList.metadata.gearItemsCreated > 0) {
        result.warnings.push(`Created ${importedList.metadata.gearItemsCreated} new gear items`)
      }

    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown import error'
      result.errors.push(`Import failed: ${message}`)
    }

    return result
  }

  /**
   * Get a unique list name by appending (duplicate) suffix if needed
   */
  private async getUniqueListName(proposedName: string): Promise<string> {
    const listRepository = createListRepository(this.userId)
    const existingLists = await listRepository.list()
    const existingNames = new Set(existingLists.map(list => list.name.toLowerCase()))

    let finalName = proposedName
    let counter = 0

    while (existingNames.has(finalName.toLowerCase())) {
      counter++
      finalName = counter === 1 
        ? `${proposedName} (duplicate)`
        : `${proposedName} (duplicate ${counter})`
    }

    return finalName
  }

  /**
   * Execute the complete import in a single database transaction
   */
  private async executeTransactionalImport(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      categoriesCreated: number  
      listedGearItemsCreated: number
    }
  }> {
    // Use Supabase transaction to ensure atomicity
    const { data, error } = await supabase.rpc('import_complete_list', {
      p_user_id: this.userId,
      p_list_data: parseResult.list,
      p_categories_data: parseResult.categories,
      p_listed_gear_items_data: parseResult.listedGearItems
    })

    if (error) {
      // If RPC doesn't exist, fall back to manual transaction
      if (error.message.includes('function import_complete_list')) {
        return this.executeManualTransaction(parseResult)
      }
      throw error
    }

    return data
  }

  /**
   * Manual transaction implementation as fallback
   * This creates all records step by step within a transaction
   * For list imports, we reuse existing gear items but always create new list structure
   */
  private async executeManualTransaction(parseResult: ListParseResult): Promise<{
    list: List
    metadata: {
      gearItemsCreated: number
      gearItemsReused: number
      categoriesCreated: number
      listedGearItemsCreated: number
    }
  }> {
    const metadata = {
      gearItemsCreated: 0,
      gearItemsReused: 0,
      categoriesCreated: 0,
      listedGearItemsCreated: 0
    }

    // Note: Supabase doesn't support client-side transactions
    // Each operation is atomic, but we'll handle errors by cleaning up manually if needed
    let createdList: List | null = null
    let createdCategories: ListCategory[] = []
    let createdGearItems: GearItem[] = []

    try {
      // 1. Create the list
      const { data: listData, error: listError } = await supabase
        .from('lists')
        .insert({
          name: parseResult.list.name,
          user_id: this.userId,
          gear_ids: [] // Will be populated after creating listed items
        })
        .select()
        .single()

      if (listError) throw listError
      createdList = listData

      // 2. Create all categories
      const categoryInserts = parseResult.categories.map(category => ({
        list_id: createdList.id,
        name: category.name,
        sort_index: category.sort_index,
        icon: category.icon,
        color: category.color
      }))

      const { data: categoriesData, error: categoriesError } = await supabase
        .from('list_categories')
        .insert(categoryInserts)
        .select()

      if (categoriesError) throw categoriesError
      createdCategories = categoriesData
      metadata.categoriesCreated = createdCategories.length

      // Create category name to ID mapping
      const categoryMap = new Map<string, string>()
      createdCategories.forEach(cat => categoryMap.set(cat.name, cat.id))

      // 3. Handle gear items - check for existing items first, create new ones only if needed
      // Get existing gear items for this user
      const { data: existingGear, error: existingGearError } = await supabase
        .from('gear_items')
        .select('*')
        .eq('user_id', this.userId)

      if (existingGearError) throw existingGearError

      // Create a map of existing gear items by description + weight
      const existingGearMap = new Map<string, GearItem>()
      existingGear.forEach(gear => {
        const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
        existingGearMap.set(key, gear)
      })

      // Identify which gear items need to be created vs reused
      const gearToCreate: typeof parseResult.listedGearItems[0]['gearItem'][] = []
      const gearMap = new Map<string, string>() // key -> gear_id mapping

      // First pass: identify unique gear items and check for existing ones
      const uniqueGearItems = new Map<string, ParsedListedGearItem>()
      parseResult.listedGearItems.forEach(item => {
        const key = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        if (!uniqueGearItems.has(key)) {
          uniqueGearItems.set(key, item)
        }
      })

      // Second pass: determine what needs to be created
      uniqueGearItems.forEach((item, key) => {
        const existingItem = existingGearMap.get(key)
        if (existingItem) {
          // Reuse existing item
          gearMap.set(key, existingItem.id)
          metadata.gearItemsReused++
        } else {
          // Need to create new item
          gearToCreate.push(item.gearItem)
        }
      })

      // Create new gear items if needed
      if (gearToCreate.length > 0) {
        const gearInserts = gearToCreate.map(item => ({
          user_id: this.userId,
          description: item.description,
          item_type: item.item_type,
          brand: item.brand,
          model: item.model,
          weight_g: item.weight_g,
          weight_unit_display: item.weight_unit_display || 'g',
          consumable: item.consumable,
          price: item.price,
          notes: item.notes,
          image_url: item.image_url,
          url: item.url
        }))

        const { data: gearData, error: gearError } = await supabase
          .from('gear_items')
          .insert(gearInserts)
          .select()

        if (gearError) throw gearError
        createdGearItems = gearData
        metadata.gearItemsCreated = createdGearItems.length

        // Add newly created gear to the mapping
        createdGearItems.forEach(gear => {
          const key = `${gear.description.toLowerCase().trim()}-${gear.weight_g}`
          gearMap.set(key, gear.id)
        })
      }

      // 4. Create listed gear items
      const listedItemInserts = parseResult.listedGearItems.map(item => {
        const gearKey = `${item.gearItem.description.toLowerCase().trim()}-${item.gearItem.weight_g}`
        const gearId = gearMap.get(gearKey)
        const categoryId = categoryMap.get(item.categoryName)

        if (!gearId || !categoryId) {
          throw new Error(`Failed to map gear item or category: ${item.gearItem.description}`)
        }

        return {
          gear_id: gearId,
          list_category_id: categoryId,
          quantity: item.quantity,
          worn: item.worn,
          weight_g_override: item.weight_g_override,
          notes: item.notes,
          sort_index: item.sort_index
        }
      })

      const { data: listedItemsData, error: listedItemsError } = await supabase
        .from('listed_gear_items')
        .insert(listedItemInserts)
        .select()

      if (listedItemsError) throw listedItemsError
      metadata.listedGearItemsCreated = listedItemsData.length

      // 5. Update list with gear_ids (for legacy compatibility)
      const allGearIds = Array.from(gearMap.values())
      const { error: updateError } = await supabase
        .from('lists')
        .update({ gear_ids: allGearIds })
        .eq('id', createdList.id)

      if (updateError) throw updateError

      return {
        list: { ...createdList, gear_ids: allGearIds },
        metadata
      }

    } catch (error) {
      // Manual cleanup on error - delete created records in reverse order
      try {
        // Delete listed gear items (they would be orphaned anyway)
        // Note: They should cascade delete with categories

        // Delete categories (should cascade delete listed items)
        if (createdCategories.length > 0) {
          await supabase
            .from('list_categories')
            .delete()
            .in('id', createdCategories.map(c => c.id))
        }

        // Delete the list (should cascade delete categories)
        if (createdList) {
          await supabase
            .from('lists')
            .delete()
            .eq('id', createdList.id)
        }

        // Delete newly created gear items (only ones we created for this import)
        if (createdGearItems.length > 0) {
          await supabase
            .from('gear_items')
            .delete()
            .in('id', createdGearItems.map(g => g.id))
        }
      } catch (cleanupError) {
        console.error('Failed to cleanup after import error:', cleanupError)
      }

      throw error
    }
  }
}

export const createImportService = (userId: string) => new ImportService(userId)

-- Drop and recreate gear_items table with new schema
-- WARNING: This will delete all existing gear data!

-- First, disable RLS and drop dependent objects
DROP POLICY IF EXISTS "Users can view their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can insert their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can update their own gear items" ON gear_items;
DROP POLICY IF EXISTS "Users can delete their own gear items" ON gear_items;

-- Drop indexes
DROP INDEX IF EXISTS idx_gear_items_user_id;
DROP INDEX IF EXISTS idx_gear_items_category;

-- Drop triggers
DROP TRIGGER IF EXISTS update_gear_items_updated_at ON gear_items;

-- Drop the table (this will also drop the listed_gear_items foreign key constraint)
DROP TABLE IF EXISTS gear_items CASCADE;

-- Create weight unit display enum if it doesn't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'weight_unit_display') THEN
        CREATE TYPE weight_unit_display AS ENUM ('g', 'kg', 'lb', 'oz');
    END IF;
END $$;

-- Recreate gear_items table with new schema
CREATE TABLE gear_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    item_type TEXT NOT NULL,
    description TEXT NOT NULL,
    brand TEXT,
    model TEXT,
    consumable BOOLEAN NOT NULL DEFAULT false,
    price DECIMAL(10,2),
    weight_g INTEGER NOT NULL,
    weight_unit_display weight_unit_display NOT NULL,
    notes TEXT,
    image_url TEXT,
    url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE gear_items ENABLE ROW LEVEL SECURITY;

-- Create RLS policies
CREATE POLICY "Users can view their own gear items" ON gear_items
    FOR SELECT USING (user_id = auth.uid());

CREATE POLICY "Users can insert their own gear items" ON gear_items
    FOR INSERT WITH CHECK (user_id = auth.uid());

CREATE POLICY "Users can update their own gear items" ON gear_items
    FOR UPDATE USING (user_id = auth.uid());

CREATE POLICY "Users can delete their own gear items" ON gear_items
    FOR DELETE USING (user_id = auth.uid());

-- Create updated_at trigger (reuse existing function)
CREATE TRIGGER update_gear_items_updated_at
    BEFORE UPDATE ON gear_items
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- Note: This migration will break listed_gear_items foreign key constraints
-- You may need to recreate those relationships after running this migration

