import { createImportService } from './importService'
import { supabase } from './supabase'
import type { ListParseResult } from '@/utils/parser'

// Mock Supabase client
vi.mock('./supabase', () => ({
  supabase: {
    from: vi.fn(),
    rpc: vi.fn()
  }
}))

// Mock repositories
vi.mock('./listRepository', () => ({
  createListRepository: vi.fn(() => ({
    list: vi.fn().mockResolvedValue([
      { id: 'list-1', name: 'Existing List', user_id: 'user-1', gear_ids: [], created_at: '', updated_at: '' }
    ])
  }))
}))

describe('ImportService', () => {
  const mockUserId = 'test-user-123'
  let importService: ReturnType<typeof createImportService>

  beforeEach(() => {
    vi.clearAllMocks()
    importService = createImportService(mockUserId)
  })

  describe('importList', () => {
    it('should successfully import a list with categories and items', async () => {
      const parseResult: ListParseResult = {
        success: true,
        list: { name: 'Test Import List' },
        categories: [
          { name: 'Shelter', sort_index: 0, icon: null, color: null },
          { name: 'Sleep', sort_index: 1, icon: null, color: null }
        ],
        listedGearItems: [
          {
            gearItem: {
              description: 'Tent',
              item_type: 'Shelter',
              brand: 'TestBrand',
              model: null,
              weight_g: 1000,
              weight_unit_display: 'g',
              consumable: false,
              price: null,
              notes: null,
              image_url: null,
              url: null
            },
            categoryName: 'Shelter',
            quantity: 1,
            worn: false,
            sort_index: 0,
            weight_g_override: null,
            notes: null
          }
        ],
        errors: [],
        warnings: []
      }

      // Mock successful RPC call
      const mockRpcResponse = {
        list: {
          id: 'new-list-id',
          name: 'Test Import List',
          user_id: mockUserId,
          gear_ids: ['gear-1'],
          created_at: '2024-01-01',
          updated_at: '2024-01-01'
        },
        metadata: {
          gearItemsCreated: 1,
          gearItemsReused: 0,
          categoriesCreated: 2,
          listedGearItemsCreated: 1
        }
      }

      vi.mocked(supabase.rpc).mockResolvedValueOnce({
        data: mockRpcResponse,
        error: null
      })

      const result = await importService.importList(parseResult)

      expect(result.success).toBe(true)
      expect(result.list).toEqual(mockRpcResponse.list)
      expect(result.metadata).toEqual(mockRpcResponse.metadata)
      expect(result.errors).toHaveLength(0)

      // Verify RPC was called with correct parameters
      expect(supabase.rpc).toHaveBeenCalledWith('import_complete_list', {
        p_user_id: mockUserId,
        p_list_data: parseResult.list,
        p_categories_data: parseResult.categories,
        p_listed_gear_items_data: parseResult.listedGearItems
      })
    })

    it('should handle duplicate list names by appending suffix', async () => {
      const parseResult: ListParseResult = {
        success: true,
        list: { name: 'Existing List' }, // Same name as mock existing list
        categories: [{ name: 'Gear', sort_index: 0, icon: null, color: null }],
        listedGearItems: [
          {
            gearItem: {
              description: 'Test Item',
              item_type: 'Gear',
              brand: null,
              model: null,
              weight_g: 100,
              weight_unit_display: 'g',
              consumable: false,
              price: null,
              notes: null,
              image_url: null,
              url: null
            },
            categoryName: 'Gear',
            quantity: 1,
            worn: false,
            sort_index: 0,
            weight_g_override: null,
            notes: null
          }
        ],
        errors: [],
        warnings: []
      }

      // Mock successful RPC call
      vi.mocked(supabase.rpc).mockResolvedValueOnce({
        data: {
          list: {
            id: 'new-list-id',
            name: 'Existing List (duplicate)',
            user_id: mockUserId,
            gear_ids: [],
            created_at: '2024-01-01',
            updated_at: '2024-01-01'
          },
          metadata: {
            gearItemsCreated: 1,
            gearItemsReused: 0,
            categoriesCreated: 1,
            listedGearItemsCreated: 1
          }
        },
        error: null
      })

      const result = await importService.importList(parseResult)

      expect(result.success).toBe(true)
      expect(result.warnings).toContain('List name changed from "Existing List" to "Existing List (duplicate)" to avoid duplicates')

      // Verify RPC was called with renamed list
      expect(supabase.rpc).toHaveBeenCalledWith(
        'import_complete_list',
        expect.objectContaining({
          p_list_data: { name: 'Existing List (duplicate)' }
        })
      )
    })

    it('should fail when no items to import', async () => {
      const parseResult: ListParseResult = {
        success: true,
        list: { name: 'Empty List' },
        categories: [],
        listedGearItems: [], // No items
        errors: [],
        warnings: []
      }

      const result = await importService.importList(parseResult)

      expect(result.success).toBe(false)
      expect(result.errors).toContain('No items to import')
      expect(supabase.rpc).not.toHaveBeenCalled()
    })

    it('should handle RPC errors gracefully', async () => {
      const parseResult: ListParseResult = {
        success: true,
        list: { name: 'Test List' },
        categories: [{ name: 'Category', sort_index: 0, icon: null, color: null }],
        listedGearItems: [
          {
            gearItem: {
              description: 'Item',
              item_type: 'Category',
              brand: null,
              model: null,
              weight_g: 100,
              weight_unit_display: 'g',
              consumable: false,
              price: null,
              notes: null,
              image_url: null,
              url: null
            },
            categoryName: 'Category',
            quantity: 1,
            worn: false,
            sort_index: 0,
            weight_g_override: null,
            notes: null
          }
        ],
        errors: [],
        warnings: []
      }

      // Mock RPC error that's not about missing function (so it won't fall back)
      vi.mocked(supabase.rpc).mockResolvedValueOnce({
        data: null,
        error: new Error('Permission denied')
      })

      const result = await importService.importList(parseResult)

      expect(result.success).toBe(false)
      console.log('Actual errors:', result.errors)
      expect(result.errors).toContain('Import failed: Permission denied')
    })

    it('should include metadata about reused gear items', async () => {
      const parseResult: ListParseResult = {
        success: true,
        list: { name: 'Test List' },
        categories: [{ name: 'Gear', sort_index: 0, icon: null, color: null }],
        listedGearItems: [
          {
            gearItem: {
              description: 'Existing Item',
              item_type: 'Gear',
              brand: null,
              model: null,
              weight_g: 100,
              weight_unit_display: 'g',
              consumable: false,
              price: null,
              notes: null,
              image_url: null,
              url: null
            },
            categoryName: 'Gear',
            quantity: 1,
            worn: false,
            sort_index: 0,
            weight_g_override: null,
            notes: null
          }
        ],
        errors: [],
        warnings: []
      }

      const mockRpcResponse = {
        list: {
          id: 'new-list-id',
          name: 'Test List',
          user_id: mockUserId,
          gear_ids: ['existing-gear-1'],
          created_at: '2024-01-01',
          updated_at: '2024-01-01'
        },
        metadata: {
          gearItemsCreated: 0,
          gearItemsReused: 1,
          categoriesCreated: 1,
          listedGearItemsCreated: 1
        }
      }

      vi.mocked(supabase.rpc).mockResolvedValueOnce({
        data: mockRpcResponse,
        error: null
      })

      const result = await importService.importList(parseResult)

      expect(result.success).toBe(true)
      expect(result.metadata?.gearItemsReused).toBe(1)
      expect(result.warnings).toContain('Reused 1 existing gear items from your library')
    })
  })
})

