import { describe, it, expect } from 'vitest'
import { parseCsv } from './csv'
import { validateGearItems, checkForDuplicates } from './index'

describe('CSV Parser', () => {
  describe('parseCsv', () => {
    it('should parse basic CSV with required fields', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter
Sleeping Bag,800g,Sleep System`

      const result = parseCsv(csv, 'Test List')

      expect(result.success).toBe(true)
      expect(result.listedGearItems).toHaveLength(2)
      expect(result.errors).toHaveLength(0)

      expect(result.listedGearItems[0].gearItem).toMatchObject({
        description: 'Tent',
        weight_g: 1200,
        item_type: 'Shelter',
        consumable: false
      })
    })

    it('should handle different weight units', () => {
      const csv = `name,weight
Item1,2.5oz
Item2,1200g
Item3,1.5 oz`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.listedGearItems[0].gearItem.weight_g).toBeCloseTo(71, 0) // 2.5oz ≈ 71g
      expect(result.listedGearItems[1].gearItem.weight_g).toBe(1200)
      expect(result.listedGearItems[2].gearItem.weight_g).toBeCloseTo(43, 0) // 1.5oz ≈ 43g
    })

    it('should handle quoted fields with commas', () => {
      const csv = `name,weight,description
"Tent, 2-person",1200g,"Lightweight, waterproof"
Stove,150g,"Compact, efficient"`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.listedGearItems[0].gearItem.description).toBe('Tent, 2-person')
      expect(result.listedGearItems[0].gearItem.notes).toBe('Lightweight, waterproof')
    })

import { 
  type ParsedGearItem, 
  type GearParseResult, 
  type ColumnMap,
  parseWeightFromText, 
  parseBoolean, 
  validateParsedGearItem 
} from './index'


// Common CSV column mappings for LighterPack exports with intelligent detection
const COLUMN_MAPPINGS = {
  description: ['name', 'item name', 'item', 'gear name', 'product', 'label', 'description'],
  brand: ['brand', 'manufacturer', 'make'],
  weight: ['weight', 'weight (g)', 'weight (grams)', 'weight_grams', 'wt', 'oz', 'grams'],
  item_type: ['category', 'type', 'gear type', 'class', 'item_type'],
  consumable: ['consumable', 'consumables', 'is consumable'],
  price: ['price', 'cost', 'msrp', 'value'],
  notes: ['notes', 'note', 'comments'],
  url: ['url', 'link', 'product url', 'website']
}

// Legacy function for backward compatibility - converts gear only
function parseCsvAsGear(csvContent: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: []
  }

  try {
    const lines = csvContent.trim().split('\n')
    if (lines.length < 2) {
      result.errors.push('CSV must have at least a header row and one data row')
      return result
