      return result
    }

    if (columnMap.weight === undefined) {
      result.success = false
      result.errors.push('No weight column found. Required columns: description, weight')
      return result
    }

    // Parse each row
    for (let i = 0; i < allParsedRows.length; i++) {
      const row = allParsedRows[i]
      if (row.length === 0 || row.every(cell => !cell.trim())) continue

      try {
        const item = parseRowToGearItem(row, columnMap, headers)
        const validationErrors = validateParsedGearItem(item)

        if (validationErrors.length > 0) {
          result.errors.push(`Row ${i + 2}: ${validationErrors.join(', ')}`)
          continue
        }

        result.data.push(item)
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.errors.push(`Row ${i + 2}: ${message}`)
      }
    }

    // Check for duplicates within the parsed data
    const { unique, duplicates } = findDuplicates(result.data)
    result.data = unique

    if (duplicates.length > 0) {
      result.warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar description/weight/brand)`)
    }

    result.success = result.data.length > 0
    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseRow(line: string): string[] {
  const result: string[] = []
  let current = ''
  let inQuotes = false
  let i = 0

  while (i < line.length) {
    const char = line[i]

    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"'
        i += 2
        continue
      }
      inQuotes = !inQuotes
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim())
      current = ''
    } else {
      current += char
    }
    i++
  }

  result.push(current.trim())
  return result
}

function mapColumns(headers: string[], rows: string[][]): ColumnMap {
  const map: ColumnMap = {}

  for (const [field, possibleNames] of Object.entries(COLUMN_MAPPINGS)) {
    for (let i = 0; i < headers.length; i++) {
      const header = headers[i].toLowerCase().trim()
      if (possibleNames.some(name => header.includes(name.toLowerCase()))) {
        map[field] = i
        break
      }
    }
  }

  return map
}

function parseRowToGearItem(values: string[], columnMap: ColumnMap, headers: string[]): ParsedGearItem {
  const getValue = (field: string): string => {
    const index = columnMap[field]
    return index !== undefined ? values[index]?.trim() || '' : ''
  }

  // Check column structure for smart mapping
  const hasNameColumn = headers.some(h => ['name', 'item name', 'item', 'gear name', 'product', 'label'].includes(h.toLowerCase().trim()))
  const hasDescColumn = headers.some(h => ['description'].includes(h.toLowerCase().trim()))

  // Required fields
  const description = getValue('description')
  if (!description) {
    throw new Error('Item description is required')
  }

  const weightStr = getValue('weight')
  if (!weightStr) {
    throw new Error('Weight is required')
  }

  const { grams: weight_g, unit: weight_unit_display } = parseWeightFromText(weightStr)

  // Optional fields with fallbacks
  const brand = getValue('brand') || undefined
  const item_type = getValue('item_type') || 'Other'

  // Brand detection removed - preserve original data only

  // Keep item_type as provided in CSV, no automatic categorization

  const consumable = parseBoolean(getValue('consumable'))
  const priceStr = getValue('price')
  const price = priceStr ? parseFloat(priceStr.replace(/[$,]/g, '')) : undefined
  // Smart notes handling: 
  // If we have both name and description columns, put description content in notes
  // If we only have description column, it's already used as main description
  let notes = getValue('notes') || undefined

  if (!notes && hasNameColumn && hasDescColumn) {
    // We have separate name and description columns, so put description in notes
    notes = headers.map((h, i) => h.toLowerCase().trim() === 'description' ? values[i]?.trim() : null).find(v => v) || undefined
  }
  const url = getValue('url') || undefined

  return {
    description,
    brand: brand || null,
    model: null, // CSV rarely has model info separate from description
    weight_g,
    weight_unit_display,
    item_type,
    consumable,
    price: price || null,
    notes: notes || null,
    image_url: null, // CSV doesn't contain images
    url: url || null
  }
}

function findDuplicates(items: ParsedGearItem[]): { unique: ParsedGearItem[], duplicates: { item: ParsedGearItem, duplicateOf: number }[] } {
  const unique: ParsedGearItem[] = []
  const duplicates: { item: ParsedGearItem, duplicateOf: number }[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if descriptions match (case-insensitive)
      const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

      // Check if brands match (case-insensitive, treating null/undefined as empty)
      const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

      if (descriptionsMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  return { unique, duplicates }
}

export function parseCsv(csvContent: string, listName: string = 'Imported List'): ListParseResult {
  const result: ListParseResult = {
    success: false,
    list: { name: listName },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: []
  }

  try {
    const lines = csvContent.trim().split('\n')
    if (lines.length < 2) {
      result.errors.push('CSV must have at least a header row and one data row')
      return result
    }

    const headers = parseRow(lines[0])
    const allParsedRows = lines.slice(1).map(line => parseRow(line))

    // Create column mapping with intelligent detection
    const columnMap = mapColumns(headers, allParsedRows)

    if (columnMap.description === undefined) {
      result.errors.push('No description/item column found. Required columns: description, weight')
      return result
    }

    if (columnMap.weight === undefined) {
      result.errors.push('No weight column found. Required columns: description, weight')
      return result
    }

    // Parse all rows into items and categories
    const categoryMap = new Map<string, number>()
    let globalSortIndex = 0

    for (let i = 0; i < allParsedRows.length; i++) {
      const row = allParsedRows[i]

      // Skip empty rows
      if (row.every(cell => !cell?.trim())) {
        continue
      }

      try {
        // Parse basic item fields
        const description = row[columnMap.description!]?.trim()
        if (!description) {
          result.warnings.push(`Row ${i + 2}: Skipping empty item`)
          continue
        }

        const weightText = row[columnMap.weight!]
        const { grams, unit } = parseWeightFromText(weightText)

        // Determine category
        let categoryName = 'Imported Items' // Default category
        if (columnMap.category !== undefined) {
          categoryName = row[columnMap.category]?.trim() || categoryName
        } else if (columnMap.item_type !== undefined) {
          // Use item_type as category if no explicit category column
          categoryName = row[columnMap.item_type]?.trim() || categoryName
        }

        // Add category if new
        if (!categoryMap.has(categoryName)) {
          const sortIndex = categoryMap.size
          result.categories.push({
            name: categoryName,
            sort_index: sortIndex,
            icon: null,
            color: null
          })
          categoryMap.set(categoryName, sortIndex)
        }

        // Create the gear item
        const item: ParsedGearItem = {
          description,
          brand: columnMap.brand !== undefined ? row[columnMap.brand] || null : null,
          model: null,
          weight_g: grams,
          weight_unit_display: unit,
          item_type: columnMap.item_type !== undefined ? row[columnMap.item_type] || categoryName : categoryName,
          consumable: columnMap.consumable !== undefined ? parseBoolean(row[columnMap.consumable]) : false,
          price: columnMap.price !== undefined ? parseFloat(row[columnMap.price]) || null : null,
          notes: columnMap.notes !== undefined ? row[columnMap.notes] || null : null,
          image_url: null,
          url: columnMap.url !== undefined ? row[columnMap.url] || null : null
        }

        // Validate the item
        const itemErrors = validateParsedGearItem(item)
        if (itemErrors.length > 0) {
          result.warnings.push(`Row ${i + 2}: ${itemErrors.join(', ')}`)
          continue
        }

        // Parse list-specific fields
        const quantity = columnMap.quantity !== undefined 
          ? parseInt(row[columnMap.quantity]) || 1 
          : 1
        const worn = columnMap.worn !== undefined 
          ? parseBoolean(row[columnMap.worn]) 
          : false

        // Add as listed gear item
        result.listedGearItems.push({
          gearItem: item,
          categoryName,
          quantity,
          worn,
          sort_index: globalSortIndex++,
          weight_g_override: null,
          notes: null
        })

      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Row ${i + 2}: ${message}`)
      }
    }

    // Ensure we have at least one category if we have items
    if (result.listedGearItems.length > 0 && result.categories.length === 0) {
      result.categories.push({
        name: 'Imported Items',
        sort_index: 0,
        icon: null,
        color: null
      })
    }

    result.success = result.listedGearItems.length > 0

    if (result.listedGearItems.length === 0) {
      result.errors.push('No valid items found in CSV')
    } else {
      result.warnings.push(`Imported ${result.listedGearItems.length} items across ${result.categories.length} categories`)
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

